import openpyxl, re

wb = openpyxl.load_workbook('init.xlsx')

data = {'PUR PURCHASE': [], 'PUR PAID': [], 'CASH SS': [], 'EXPRR': []}

for sh in ['CMSN', 'CSTR', 'EXPRO']:
    ws = wb[sh]
    for row in ws.iter_rows(min_row=2):
        ref = row[1].value
        if ref is None:
            continue
        amt = row[2].value if row[2].value is not None else row[3].value
        ref = str(ref)
        for key in data:
            if ref.startswith(key):
                data[key].append((ref, amt))
                break

def sortkey(ref):
    m = re.search(r'(\d+)$', ref)
    return int(m.group(1)) if m else 0

for key in data:
    data[key].sort(key=lambda x: sortkey(x[0]))

layout = {
    'PUR PURCHASE': ('A', 'B', 'C'),
    'PUR PAID': ('E', 'F', 'G'),
    'CASH SS': ('I', 'J', 'K'),
    'EXPRR': ('L', 'M', 'N'),
}

headers = {
    'PUR PURCHASE': ('ITEM', 'PUR PURCHASE', 'AMOUNT'),
    'PUR PAID': ('ITEM', 'PUR PAID', 'AMOUNT'),
    'CASH SS': ('ITEM', 'CASH SS', 'AMOUNT'),
    'EXPRR': ('ITEM', 'EXPRR', 'AMOUNT'),
}

ws = wb['OUT CAS']

for key, (ic, dc, ac) in layout.items():
    ws[f'{ic}1'] = headers[key][0]
    ws[f'{dc}1'] = headers[key][1]
    ws[f'{ac}1'] = headers[key][2]

for key, (ic, dc, ac) in layout.items():
    items = data[key]
    r = 2
    for i, (ref, amt) in enumerate(items, start=1):
        ws[f'{ic}{r}'] = i
        ws[f'{dc}{r}'] = ref
        ws[f'{ac}{r}'] = amt
        r += 1
    ws[f'{dc}{r}'] = 'TOTAL'
    ws[f'{ac}{r}'] = f'=SUM({ac}2:{ac}{r-1})'

wb.save('output.xlsx')
print('saved')
for key in data:
    print(key, len(data[key]))
